// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 initialBalance, uint256 amount) public {
        // Keep the fuzzed domain wide but within practical bounds.
        initialBalance = bound(initialBalance, 0, 1 ether);
        amount = bound(amount, 0, initialBalance);

        // Deploy a live LogFile so Deposit/Collect external calls succeed.
        LogFile log = new LogFile();

        // Required setup: set the log file before initialization.
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();

        address actor = address(0xBEEF);
        vm.deal(actor, initialBalance);

        // The caller deposits and then collects a valid amount.
        vm.prank(actor);
        c.Deposit{value: initialBalance}();

        uint256 preBalance = c.balances(actor);

        vm.prank(actor);
        c.Collect(amount);

        // General rule: after a successful Collect, the caller's stored balance
        // must be reduced by exactly the collected amount.
        assertTrue(c.balances(actor) == preBalance - amount);
    }
}

contract LogFile
{
    struct Message
    {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
